import React, { useState, useEffect } from "react";
import { useAuthorize } from "../context/hook/useAuthorization";
import { DatePicker, Input, Table } from 'antd';
import NavMenu from "./SharedComponents/navMenu";
import { SearchOutlined } from '@ant-design/icons';
import '../styles/myaccount.css';
import 'animate.css';
import moment from 'moment';

const { RangePicker } = DatePicker;

const Record = (props) => {
    const { userAccount } = useAuthorize();
    const [workspaces, setWorkspaces] = useState([]);
    const [loading, setLoading] = useState(false);
    const [date, setDate] = useState(moment().format('YYYY-MM-DD')); // Default to today's date

    useEffect(() => {
        const fetchWorkspaces = async () => {
            setLoading(true);
            const url = `/api/workspaces/available?date=${date}`;
            console.log("Fetching from:", url); 
            try {
                const response = await fetch(url, {
                    headers: {
                        'Authorization': `Bearer ${userAccount.userToken}`
                    }
                });
                const data = await response.json();
                console.log("Received data:", data); 
                if (response.ok) {
                    setWorkspaces(data);
                } else {
                    throw new Error(data.error || "Failed to fetch workspaces");
                }
            } catch (error) {
                console.error("Fetching error:", error);
            } finally {
                setLoading(false);
            }
        };

        if (userAccount) {
            fetchWorkspaces();
        }
    }, [userAccount, date]);

    const handleDateChange = (date, dateString) => {
        setDate(dateString);
    };

    const columns = [
        { title: 'Name', dataIndex: 'name', key: 'name' },
        { title: 'Location', dataIndex: 'location', key: 'location' },
        { title: 'Status', dataIndex: 'status', key: 'status' }
    ];

    return (
        <div className="recordpage">
            <NavMenu isAdmin={true} breadcrum="Workspace Overview" pagePath="/workspace-overview" />
            <div className="workspace-overview animate__animated animate__fadeInUp">
                <DatePicker onChange={handleDateChange} format="YYYY-MM-DD" />
                <Table columns={columns} dataSource={workspaces} loading={loading} rowKey="_id" />
            </div>
        </div>
    );
};

export default Record;






